'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var zeros = require( '@stdlib/array/zeros' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var gpermuteRows = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, N ) {
	var workspace;
	var sa1;
	var sa2;
	var ip;
	var A;
	var i;

	if ( isColumnMajor( order ) ) {
		sa1 = 1;
		sa2 = N;
	} else {
		sa1 = N;
		sa2 = 1;
	}
	A = zeros( N*N, 'generic' );
	ip = zeros( N, 'generic' );
	workspace = zeros( N, 'generic' );
	for ( i = 0; i < N; i++ ) {
		ip[ i ] = i;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var k;
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			k = ( i % ( N - 1 ) ) + 1;
			ip[ 0 ] = k;
			ip[ k ] = 0;
			z = gpermuteRows( N, N, A, sa1, sa2, 0, ip, 1, 0, workspace, 1, 0 );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
			f = createBenchmark( ord, N );
			bench( format( '%s::square_matrix:ndarray:order=%s,size=%d', pkg, ord, N*N ), f );
		}
	}
}

main();
